import java.util.*;import java.util.jar.*;import org.objectweb.asm.tree.*;import static org.objectweb.asm.Opcodes.*;
public final class SourceLightningHpDelta {
 static final String P="local/lito381/server/",PC=P+"ClientSession",N=P+"NativeSourceLightningHp",EVENT=P+"NativePlayerCommit$Event",COMMIT=P+"NativePlayerCommit";
 static void need(boolean b,String s){if(!b)throw new AssertionError(s);}
 public static void main(String[]a)throws Exception{try(var base=new JarFile(a[0]);var jar=new JarFile(a[1])){var names=new HashSet<String>();var changed=new HashSet<String>();for(var e:Collections.list(base.entries())){names.add(e.getName());var next=jar.getJarEntry(e.getName());need(next!=null,"no removed entries");if(!Arrays.equals(base.getInputStream(e).readAllBytes(),jar.getInputStream(next).readAllBytes()))changed.add(e.getName());}var fresh=new HashSet<String>();for(var e:Collections.list(jar.entries()))if(!names.contains(e.getName()))fresh.add(e.getName());need(changed.equals(Set.of(PC+".class",EVENT+".class",COMMIT+".class"))&&fresh.equals(Set.of(N+".class",N+"$Linked.class")),"exact archive delta");int ports=0,frames=0;
 for(var name:List.of(PC,EVENT,COMMIT)){var old=FreezeSourceTargetDelta.read(base,name);var now=FreezeSourceTargetDelta.read(jar,name);need(old.fields.size()==now.fields.size()&&old.methods.size()==now.methods.size(),"no production schema changes");for(int i=0;i<old.fields.size();i++){var f=old.fields.get(i);var g=now.fields.get(i);need(f.name.equals(g.name)&&f.desc.equals(g.desc)&&f.access==g.access&&Objects.equals(f.value,g.value),"original field");}
 for(var m:old.methods){var actual=now.methods.stream().filter(x->x.name.equals(m.name)&&x.desc.equals(m.desc)).findFirst().orElseThrow();if(name.equals(PC)&&m.name.equals("nativeStaticOriginalFrame")){var nodes=new ArrayList<AbstractInsnNode>();for(var n:actual.instructions)if(n.getOpcode()>=0&&nodes.size()<5)nodes.add(n);need(nodes.get(2)instanceof MethodInsnNode call&&call.owner.equals(N)&&call.name.equals("allowFrame")&&nodes.get(3).getOpcode()==IFNE&&nodes.get(4).getOpcode()==RETURN,"bounded final-frame guard");for(var n:nodes)actual.instructions.remove(n);frames++;}for(var n:actual.instructions.toArray())if(n instanceof MethodInsnNode call&&call.owner.equals(N)){if(name.equals(EVENT)&&m.name.equals("<init>")&&call.name.equals("link"))call.owner=P+"NativeAcceptedFreezeMutation";else if(name.equals(COMMIT)&&m.name.equals("drain")&&call.name.equals("enqueue"))call.owner=P+"NativeAcceptedHpCompletion";else throw new AssertionError("unexpected port");ports++;}need(Arrays.equals(FreezeSourceTargetDelta.body(old,m,m.name,m.access),FreezeSourceTargetDelta.body(now,actual,m.name,m.access)),"every original method inverse "+name+"."+m.name);}}
 need(ports==2&&frames==1,"two bounded event/completion ports and one frame guard");for(var name:List.of(N,N+"$Linked")){var c=FreezeSourceTargetDelta.read(jar,name);for(var f:c.fields)need((f.access&ACC_STATIC)==0,"no global actor registry");for(var m:c.methods)for(var n:m.instructions)if(n instanceof TypeInsnNode t&&t.getOpcode()==NEW)need(!Set.of("java/lang/Thread","java/lang/ThreadLocal").contains(t.desc)&&!t.desc.contains("Executor"),"no workers/TLS");else if(n instanceof MethodInsnNode call)need(!call.owner.startsWith("java/sql/")&&!call.owner.startsWith("java/nio/file/")&&!call.owner.contains("GameStateStore"),"no persistence");}
 }System.out.println("PASS independent archive/schema/every-original-method inverse; original HP mutation and worker authority retained");}
}
